// (5) lib/segment/src/spaces/simple.rs L228-235 — 归一化无溢出防护
pub fn cosine_preprocess(vector: DenseVector) -> DenseVector {
    let mut length: f32 = vector.iter().map(|x| x * x).sum();  // [inf x4] → length = inf
    if is_length_zero_or_normalized(length) { return vector; }  // tools.rs L15: length<EPSILON || |length-1|<=1e-6 → inf 两支均 false
    length = length.sqrt();                                     // sqrt(inf) = inf
    vector.iter().map(|x| x / length).collect()                 // inf/inf = NaN  ← 静默产生 NaN 存储
}

